INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88818, 'spa', 'vengador de sangre', 'Participio Qal sustantivado en la colocación גֹּאֵל הַדָּם: el vengador de sangre, el pariente que persigue y ejecuta al homicida. Concentrado en Números 35:12-27 y Josué 20:2-9, donde las ciudades de refugio protegen al homicida involuntario del vengador. El español vengador de sangre, el francés vengeur du sang y el árabe ثَأَرُ الدَّم distinguen claramente este sentido judicial-retributivo del redentor y el rescatador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88819, 'spa', 'pariente redentor', 'Participio Qal sustantivado: el גֹּאֵל como pariente redentor, el familiar cercano con el derecho y el deber legal de redimir propiedades, casarse con la viuda de un pariente o proteger los intereses de la familia. El libro de Rut es el texto paradigmático: Booz se identifica como גֹּאֵל (Rt 3:9, 12) y negocia con un pariente más cercano (Rt 4:1-6) antes de redimir formalmente la tierra de Noemí y tomar a Rut como esposa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88820, 'spa', 'redimir, rescatar', 'Formas finitas activas del Qal: redimir, rescatar o comprar de vuelta — el sentido transaccional central que cubre la redención de propiedades, personas en servidumbre o artículos empeñados. Levítico 25 establece el marco legal: un pariente ''redime'' un campo vendido (Lv 25:25) o a una persona vendida como esclava (Lv 25:48). Dios ''redime'' a Israel de Egipto (Ex 6:6; 15:13). El español redimir, el francés racheter y el alemán erlösen confirman este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88821, 'spa', 'Redentor divino (título)', 'Participio Qal sustantivado como epíteto divino: Dios (especialmente YHWH) como Redentor de Israel. Concentrado en Isaías 41-63, donde aparece con sufijos posesivos — ''tu Redentor, el Santo de Israel'' (Is 41:14; 43:14; 44:24; 48:17; 54:5). También en Job 19:25 (''Yo sé que mi Redentor vive'') y en los Salmos (19:14; 78:35; 103:4). El español Redentor, el francés Rédempteur y el alemán Erlöser sirven como equivalentes directos de este título teológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88825, 'spa', 'ser redimido (Nifal)', 'Nifal pasivo: ser redimido o comprado de vuelta, dicho de propiedades o personas que son objeto de redención. La legislación levítica especifica cuándo casas, campos y personas ''serán redimidos'' o ''no son redimidos'' (Lv 25:30, 49, 54; 27:20, 27, 28, 33). El español ser redimido, el francés être racheté y el alemán erlöst werden confirman la voz pasiva. Un sentido gramatical y semánticamente distinto del Qal activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88830, 'spa', 'los redimidos (participio pasivo)', 'Participio pasivo Qal sustantivado: ''los redimidos'', aquellos a quienes Dios ha redimido del exilio, la opresión o la muerte. Isaías lo emplea como designación colectiva de los exiliados que regresan — ''los redimidos de Yahvé volverán'' (Is 35:9; 51:10), y el remanente es llamado ''Los Redimidos'' (Is 62:12). El Salmo 107:2 abre con ''Díganlo los redimidos de Yahvé''. El español los redimidos y el árabe المفديون lo confirman.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88879, 'spa', 'Nifal/Pual', 'Nifal/Pual: ser contaminado, quedar profanado. Formas pasivas del nifal y pual: ser contaminado, quedar profanado o ser declarado ritualmente impuro. Sacerdotes cuyas genealogías no pudieron verificarse fueron ''excluidos del sacerdocio como contaminados'' (Esd 2:62; Neh 7:64), expresión que significa expulsados por considerarse impuros. En Isaías 59:3 y Lamentaciones 4:14, manos y vestiduras quedan manchadas de sangre. Sofonías 3:1 personifica a Jerusalén como ''la contaminada''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88881, 'spa', 'Hitpael', 'Hitpael: contaminarse a sí mismo. Forma reflexiva del hitpael: contaminarse deliberadamente o resolverse contra la autocontaminación. Daniel ''propuso en su corazón no contaminarse'' con la comida ni el vino del rey (Dn 1:8). El español ''se contaminara/se contaminaría'' preserva perfectamente la voz media reflexiva, enfatizando la agencia del sujeto en proteger o violar los límites de su pureza personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88882, 'spa', 'Piel', 'Piel: contaminar (a alguien/algo). Forma activa del piel: profanar o desecrar a alguien o algo mediante las propias acciones. En Malaquías 1:7 se desafía a los sacerdotes: ''¿En qué te contaminamos?'' — dirigiéndose directamente a YHWH, pues sus ofrendas contaminadas profanan su altar y, por extensión, su nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88884, 'spa', 'Hifil', 'Hifil: manchar, ensuciar. Forma causativa del hifil: manchar o ensuciar algo, usado metafóricamente de vestiduras empapadas en la sangre del juicio divino. En Isaías 63:3 el guerrero divino pisa el lagar solo y declara ''manché todos mis vestidos''. Este sentido va más allá de la profanación ritual hacia una imagen física vívida de sangre salpicando la tela, metáfora de la violencia del juicio escatológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88888, 'spa', 'Redención, derecho de rescate', 'El derecho legal, acto o precio de redimir propiedades o personas, arraigado en el sistema israelita de tenencia de la tierra basado en el parentesco. Concentrado en Levítico 25 (ocho de catorce apariciones), regula la redención de campos (v. 24), casas (vv. 29, 31–32) y personas esclavizadas (vv. 48, 51–52), con el precio calculado según los años restantes hasta el Jubileo. En Rut 4:6–7, גְּאֻלָּה designa el derecho del pariente redentor que el pariente más cercano declina ejercer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88895, 'spa', 'Aro de rueda', 'El aro circular o llanta de una rueda, la banda exterior curva sobre la que se asienta el neumático. Se usa para las ruedas de bronce de los carros de Salomón (1 R 7:33) y las ruedas de la visión de Ezequiel 1:18. El español ''aros'' (''anillos, aros'') capta bien la geometría, distinguiéndolo del sentido anatómico. La curvatura convexa remite a la imagen raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88896, 'spa', 'Montículo cúltico', 'Un montículo elevado y abovedado construido para el culto ilícito — el ''lugar eminente'' de Ezequiel (16:24, 31, 39). Siempre aparece emparejado con רָמָה (lugar alto) en las denuncias de Ezequiel contra la prostitución espiritual. El español ''altar'' y la conexión de la Vulgata con ''lupanar'' (del latín ''fornix'', entrada abovedada de un burdel) muestran cómo la imagen de la estructura abovedada pervivió en la tradición posterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88897, 'spa', 'Ceja', 'El arco superciliar o la ceja, usado exclusivamente en las regulaciones levíticas sobre enfermedades de la piel (Lv 14:9), donde la persona debe rasurarse ''las cejas''. El español ''cejas'' precisa este sentido con exactitud. El arco convexo sobre el ojo es otra instancia más de la idea raíz: una superficie curva y prominente del cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88898, 'spa', 'Espalda', 'La superficie dorsal de un ser vivo — literalmente, la espalda. En el Salmo 129:3, los labradores trazan surcos sobre la espalda de Israel como figura de la opresión; Ezequiel 10:12 lo aplica al cuerpo de los querubines (aunque algunos enmiendan a ''ruedas''). El español ''espalda'' y el francés ''dos'' traducen consistentemente este sentido anatómico, confirmando su concreción primaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88902, 'spa', 'Protuberancia de escudo', 'La protuberancia convexa en el centro de un escudo, usada metafóricamente en Job 13:12 y 15:26 para la arrogancia desafiante — embistiendo contra Dios ''con las gruesas protuberancias de sus escudos''. El español ''espaldas'' y el francés ''dos'' confunden este sentido con el anatómico, pero la imagen militar de la parte elevada y central del escudo es distinta. La superficie endurecida y saliente se convierte en figura de resistencia obstinada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88907, 'spa', 'Zanjas y cisternas', 'Sustantivo plural para fosos, zanjas o cisternas — hoyos excavados en el suelo para almacenar agua o con propósitos militares. En 2 Reyes 3:16 designa claramente trincheras cavadas para contener agua, mientras que en Jeremías 14:3 se refiere a cisternas buscadas por los siervos durante la sequía. El término abarca tanto usos agrícolas como defensivos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88910, 'spa', 'Foso, cueva (para animales)', 'Foso, cueva (para animales). Un foso o recinto cerrado para confinar animales, específicamente el foso de los leones en la corte del rey medo Darío. Las diez ocurrencias aparecen en Daniel 6:7-24 (sección aramea), describiendo el recinto en el que Daniel fue arrojado por orar a Dios y del cual salió ileso. El término aparece con preposición lamed para movimiento hacia el foso y en estado constructo (''foso de leones'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88915, 'spa', 'Ser altivo, actuar con soberbia — Sentido Qal de soberbia o arrogancia pecaminos', 'Ser altivo, actuar con soberbia — Sentido Qal de soberbia o arrogancia pecaminosa, cuando el corazón ''se eleva'' en autoexaltación contra Dios. El corazón de Uzías ''se enalteció hasta corromperse'' (2 Cr 26:16); Proverbios 18:12 advierte que ''antes del quebrantamiento se enaltece el corazón del hombre''; Isaías 3:16 describe a las hijas de Sion caminando con cuellos ''altivos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88916, 'spa', 'Ser físicamente alto o elevado — Sentido Qal estativo de ser físicamente alto, g', 'Ser físicamente alto o elevado — Sentido Qal estativo de ser físicamente alto, grande o elevado, describiendo la impresionante estatura de Saúl (1 S 10:23), los cielos que son más altos que la tierra (Job 35:5; Sal 103:11; Isa 55:9), o un árbol que creció alto (Ez 31:5,10). Las glosas multilingües emplean consistentemente términos de altura o estatura física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88917, 'spa', 'Ser exaltado, elevarse en honor — Sentido Qal de ser exaltado en honor, estatus ', 'Ser exaltado, elevarse en honor — Sentido Qal de ser exaltado en honor, estatus o gloria, usado positivamente de Dios cuya justicia ''es exaltada'' (Isa 5:16) y del Siervo que ''será exaltado y engrandecido'' (Isa 52:13). El corazón de Josafat ''se enalteció en los caminos de YHWH'' (2 Cr 17:6), un caso positivo poco frecuente aplicado a un ser humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88919, 'spa', 'Hacer alto, exaltar (causativo) — Sentido Hifil causativo de hacer algo alto, le', 'Hacer alto, exaltar (causativo) — Sentido Hifil causativo de hacer algo alto, levantar o exaltar activamente. Dios ''levanta al pobre del polvo'' (Sal 113:5); Manasés ''elevó la altura'' del muro (2 Cr 33:14); el que ''eleva su puerta busca la ruina'' (Pr 17:19). El causativo añade agencia: alguien produce activamente la elevación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88925, 'spa', 'Remontarse alto, volar hacia arriba — Uso Hifil especializado para remontarse o ', 'Remontarse alto, volar hacia arriba — Uso Hifil especializado para remontarse o volar a gran altura, aplicado a aves. Job 39:27 pregunta si el águila ''se remonta'' por mandato de Dios; Abdías 1:4 advierte a Edom que ''aunque te remontes como el águila,'' Dios te derribará. Job 5:7 describe chispas que ''vuelan hacia arriba''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88946, 'spa', 'Altivo, soberbio', 'Altanero, orgulloso, arrogante en disposición — extensión figurada de la altura física a la autoexaltación moral. En Sal 101:5 el salmista jura no tolerar al ''altivo de corazón''; Pr 16:5 declara a tal persona abominación. Ec 7:8 contrasta al ''de espíritu altanero'' con la paciencia. El español ''altivo'' refleja la misma transferencia metafórica de lo alto a lo arrogante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88947, 'spa', 'La dimensión física de altura — la estatura o elevación medible de personas, árb', 'La dimensión física de altura — la estatura o elevación medible de personas, árboles, edificios y estructuras. Aplicada a la imponente figura de Goliat (1 S 17:4), el vestíbulo del templo (2 Cr 3:4), las ruedas y cámaras visionarias de Ezequiel (Ez 1:18; 40:42; 41:8) y la impresionante altura de los árboles (Ez 19:11; 31:10, 14; Am 2:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88948, 'spa', 'Elevación moral o figurada — orgullo, altivez o grandeza exaltada del espíritu', 'Elevación moral o figurada — orgullo, altivez o grandeza exaltada del espíritu. Proverbios 16:18 lo empareja con רוּחַ (''espíritu'') en la célebre advertencia de que la altivez precede a la caída. Jeremías 48:29 cataloga la arrogancia de Moab, mientras que 2 Crónicas 32:26 registra el arrepentimiento de Ezequías por su ''altivez de corazón''. En Job 40:10, Dios desafía a Job a revestirse de ''dignidad y grandeza'', un raro uso positivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88963, 'spa', 'Alto, elevado, encumbrado — Altura física o espacial, describiendo montañas (Gn ', 'Alto, elevado, encumbrado — Altura física o espacial, describiendo montañas (Gn 7:19; Isa 40:9; 57:7; Ez 17:22; 40:2), murallas fortificadas (Dt 3:5; 28:52), estructuras altas como la horca de Amán (Est 5:14; 7:9), personas de gran estatura como Saúl (1 S 9:2), árboles majestuosos (Ez 17:24; 31:3) y cuernos prominentes (Dn 8:3). La fórmula ''sobre todo monte alto'' (Isa 30:25; Jer 3:6) es recurrente en la denuncia profética de la idolatría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88981, 'spa', 'frontera, límite geográfico', 'Sentido primario (188x): línea divisoria geográfica que marca el borde de un territorio. Predomina en las descripciones formulares de Números 34 y Josué 13-19, con verbos característicos como יָצָא (''salió'') y עָלָה (''subió''). Génesis 10:19 lo usa para la frontera cananea y Números 20:23 para el confín de Edom.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88987, 'spa', 'territorio, región', 'Territorio o región delimitada por fronteras (45x), con énfasis en el área interior más que en la línea. Construcciones posesivas como ''tu territorio'' (Éx 10:4, 14) y ''territorio de Israel'' desplazan el enfoque del borde al interior. Cuando las langostas entran en ''tu territorio'' (Éx 10:4), se subraya la extensión del espacio afectado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88989, 'spa', 'lindero, mojón', 'Hito o mojón con significado jurídico-ético (5x), centrado en Deuteronomio 19:14, 27:17 y Proverbios 15:25, 22:28, 23:10. Aquí el foco recae sobre la piedra que materializa el límite; moverla constituye robo e injusticia. Se diferencia del sentido 1 por su carga legal y su referencia al marcador físico más que a la línea abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89007, 'spa', 'borde, reborde de objeto', 'Borde, reborde o cornisa de un objeto construido (3x), circunscrito al altar del templo de Ezequiel (Ez 43:13, 17, 20). El español borde se aparta claramente del geográfico frontera, confirmando un sentido concreto-arquitectónico distinto. El reborde del altar cumple la función de contener la sangre sacrificial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89038, 'spa', 'Frontera, límite', 'Frontera, límite. Línea fronteriza o límite geográfico que demarca los confines territoriales. Aparece en las descripciones de reparto tribal (Nm 32:33; 34:2, 12; Jos 18:20; 19:49), en afirmaciones teológicas del ordenamiento soberano de Dios sobre los límites de la tierra (Sal 74:17; Dt 32:8), en juicios proféticos contra la remoción imperial de fronteras (Is 10:13) y en la condena moral de quienes mueven linderos para defraudar a los vulnerables (Job 24:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89045, 'spa', 'guerrero, valiente', 'Uso sustantivado para combatientes humanos: guerrero, valiente o campeón. Constituye la gran mayoría de las apariciones, designando soldados, héroes militares y hombres de valor: los valientes de David (2 S 10:7; 23:8), guerreros de diversos ejércitos (Jos 10:2; Jue 6:12) y Nimrod, ''vigoroso cazador'' (Gn 10:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89057, 'spa', 'fuerte, poderoso', 'Adjetivo atributivo que describe fuerza o capacidad inherente sin connotación guerrera específica. El león es ''el más fuerte entre las bestias'' (Pr 30:30), un hombre puede ser ''poderoso en la tierra'' (Sal 112:2) y Booz es presentado como ''varón poderoso y hacendado'' (Rt 2:1). Se distingue del sentido 1 por la ausencia del contexto bélico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89059, 'spa', 'el Poderoso, epíteto divino', 'Epíteto divino: ''el Poderoso'' o ''Dios fuerte''. En Isaías 9:6 el niño mesiánico es llamado אֵל גִּבּוֹר (''Dios fuerte''). En Deuteronomio 10:17 y Nehemías 9:32, Dios mismo es הָאֵל הַגָּדֹל הַגִּבּוֹר (''el Dios grande y poderoso''). Este sentido eleva la palabra del valor humano a la omnipotencia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89113, 'spa', 'poder, fuerza, poderío', 'poder, fuerza, poderío');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89118, 'spa', 'hechos poderosos, actos de poder', 'hechos poderosos, actos de poder');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89121, 'spa', 'valor, destreza marcial', 'valor, destreza marcial');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89131, 'spa', 'fuerza militar colectiva (metonimia)', 'fuerza militar colectiva (metonimia)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89139, 'spa', 'victoria o clamor de triunfo (pasaje disputado)', 'victoria o clamor de triunfo (pasaje disputado)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89160, 'spa', 'Calvicie frontal', 'La frente calva o parte delantera del cuero cabelludo, examinada en busca de señales de enfermedad cutánea en el procedimiento diagnóstico sacerdotal. En Lv 13:42-43 se contrapone deliberadamente a קָרַחַת (calvicie de la parte posterior), cubriendo así toda la coronilla para su inspección. En Lv 13:55 la misma lógica espacial se extiende al ''lado delantero'' de las prendas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89163, 'spa', 'Copa, tazón', 'Vasija en forma de copa o tazón, que abarca tanto recipientes funcionales para beber como ornamentos decorativos arquitectónicos que comparten la misma forma redondeada. En Génesis 44 es la copa de plata de adivinación de José, escondida en el costal de Benjamín (Gn 44:2, 12, 16, 17). En Éxodo 25 y 37, el plural designa los ornamentos en forma de cáliz de almendro en los brazos del candelabro de oro (Éx 25:31–34; 37:17–20). Jeremías 35:5 presenta copas de vino ante los recabitas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89170, 'spa', 'Reina madre', 'La reina madre o dama gobernante: una mujer con autoridad política formal como madre del rey reinante. El término aparece en 1 Reyes 11:19 para la esposa de Faraón (una dama de la corte) y en la monarquía judahíta para la madre del rey cuya posición conllevaba verdadero poder institucional. La evidencia clave es 1 Reyes 15:13, donde Asá destituye a Maacá «de gevirah», tratándolo como un cargo revocable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89177, 'spa', 'Poner límites o linderos', 'Poner límites, marcar un lindero o establecer una frontera territorial, aplicado tanto a perímetros sagrados como a límites geográficos. El imperativo Hifil en el Sinaí (Éx 19:12, 23) describe la demarcación de terreno santo para impedir el acceso no autorizado, mientras el Qal en Jos 18:20 y Dt 19:14 describe el trazado de fronteras y la prohibición de mover mojones ancestrales. Zac 9:2 extiende el uso a fronteras internacionales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89185, 'spa', 'Ciudad levítica en el territorio de Benjamín, identificada con la moderna Jaba'' ', 'Ciudad levítica en el territorio de Benjamín, identificada con la moderna Jaba'' al noreste de Jerusalén, situada cerca del estratégicamente importante paso de Micmas. Asignada a los levitas en Jos 21:17 y enumerada entre las ciudades de Benjamín (Jos 18:24). El ataque de Jonatán a la guarnición filistea allí desencadenó la guerra de independencia de Israel bajo Saúl (1 S 13:3, 16; 14:5). La expresión ''desde Geba hasta Beerseba'' marca los límites del reino de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89194, 'spa', 'colina (singular, sustantivo común)', 'colina (singular, sustantivo común)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89195, 'spa', 'colinas (plural, sustantivo común)', 'colinas (plural, sustantivo común)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89203, 'spa', 'Guibeá (nombre propio)', 'Guibeá (nombre propio)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89220, 'spa', 'Guibeá (nombre propio) — La ciudad de Guibeá en Benjamín, que aparece a lo largo', 'Guibeá (nombre propio) — La ciudad de Guibeá en Benjamín, que aparece a lo largo de su extensa historia bíblica desde los terribles sucesos de Jueces 19-20 hasta el reinado de Saúl (1 S 10:26; 22:6) y los oráculos proféticos de Oseas (9:9; 10:9). Todas las traducciones la tratan como nombre propio: en español ''Guibeá'', en francés ''Guivea'', en alemán ''Gibea''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89230, 'spa', 'Gueba (nombre propio) — Referencia a Gueba, una ciudad levítica distinta en Benj', 'Gueba (nombre propio) — Referencia a Gueba, una ciudad levítica distinta en Benjamín, a veces confundida con Guibeá por la ortografía hebrea casi idéntica. En Jueces 20:33 el contexto señala a Gueba en lugar de Guibeá propiamente dicha. Las traducciones modernas y los comentarios críticos distinguen ambos sitios de manera consistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89232, 'spa', 'Colina (sustantivo común) — El sustantivo común subyacente que significa ''colina', 'Colina (sustantivo común) — El sustantivo común subyacente que significa ''colina'' o ''altura'', empleado apelativamente y no como nombre propio. En 1 Samuel 14:2 describe un accidente geográfico del paisaje en vez de una ciudad con nombre. Este uso apelativo revela cómo muchos topónimos israelitas surgieron como simples descripciones del terreno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89234, 'spa', 'Gabaón (topónimo) — El topónimo גִּבְעוֹן, que designa una ciudad levítica en el', 'Gabaón (topónimo) — El topónimo גִּבְעוֹן, que designa una ciudad levítica en el territorio de Benjamín. Las 37 ocurrencias se refieren a esta única localidad. Funciona en cuatro núcleos narrativos principales: el tratado gabaonita (Jos 9-10), los asuntos militares y políticos de David (2 S 2:12-16; 3:30; 20:8), la ubicación del tabernáculo antes del templo (1 R 3:4; 1 Cr 16:39; 2 Cr 1:3) y las referencias proféticas (Isa 28:21; Jer 28:1; 41:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89242, 'spa', 'Gabaonita (gentilicio)', 'Adjetivo o sustantivo gentilicio que designa a un habitante de Gabaón. La mayoría de las apariciones se concentra en 2 Samuel 21:1-9, donde los gabaonitas (plural) buscan restitución de David por la transgresión de Saúl contra el antiguo pacto establecido en Josué 9. En 1 Crónicas 12:4, un guerrero gabaonita se une a las filas de David, y Nehemías 3:7 nombra a un gabaonita entre los reconstructores del muro de Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89248, 'spa', 'Qal intransitivo', 'Qal intransitivo: ser fuerte, ser poderoso, prevalecer. El relato del Diluvio (Gn 7:18-24) lo usa repetidamente cuando las aguas prevalecen sobre la tierra. También expresa superioridad militar (Éx 17:11), fortaleza tribal (Gn 49:26) y bendiciones que superan a las de los antepasados (1 Cr 5:2). El Salmo 103:11 lo extiende a la misericordia de Dios que prevalece sobre los que le temen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89251, 'spa', 'Piel e Hifil causativo', 'Piel e Hifil causativo: hacer fuerte, fortalecer o confirmar. Dios fortalece a Judá y a José (Zac 10:6, 12), un gobernante confirma un pacto con muchos (Dn 9:27), y el Salmo 12:4 advierte sobre una lengua que «se hace poderosa». El paso de intransitivo a causativo marca la transición del estado a la acción deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89252, 'spa', 'Hitpael reflexivo', 'Hitpael reflexivo: mostrarse poderoso, actuar con soberbia o desafío contra otro. Job 15:25 describe al impío extendiendo su mano contra Dios y «fortaleciéndose contra el Todopoderoso». Job 36:9 lo usa para quienes «actuaron con soberbia», e Isaías 42:13 lo aplica al Señor que se levanta como un guerrero. La raíz reflexiva añade una dimensión de autoafirmación, a veces arrogante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89270, 'spa', 'varón (fuerte/vigoroso)', 'varón (fuerte/vigoroso)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89290, 'spa', 'Sustantivo arameo que significa «hombre» o «varón», cognado del hebreo geber', 'Sustantivo arameo que significa «hombre» o «varón», cognado del hebreo geber. Se usa para individuos en contextos narrativos dramáticos: Arioc presenta a Daniel como «un hombre de los deportados» (Dn 2:25), y se habla de «un hombre en quien está el espíritu de los dioses santos» (Dn 5:11). En plural designa grupos: los hombres atados y arrojados al horno (Dn 3:20-25), los acusadores de Daniel (Dn 6:5-25) y los constructores en la correspondencia de Esdras (Esd 5:4, 10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89300, 'spa', 'Señora, soberana', 'Señora o soberana, título de autoridad imperial o política. Se emplea exclusivamente en Isaías 47:5, 7, donde la Babilonia personificada es llamada גְּבֶרֶת מַמְלָכוֹת (''señora de los reinos''), jactándose: ''Seré señora para siempre.'' El salto de la autoridad doméstica a la política es notable: no se trata de administrar un hogar, sino de dominio imperial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89301, 'spa', 'Señora, ama de casa', 'Ama de una casa, mujer que ejerce autoridad doméstica sobre siervas. El caso paradigmático es Sara como señora de Agar (Gn 16:4, 8, 9), donde el término define una jerarquía social: Agar debe someterse ''bajo la mano de tu señora.'' También se aplica a la esposa de Naamán (2 R 5:3) y se generaliza en Salmo 123:2 y Proverbios 30:23.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89308, 'spa', 'Gibetón (topónimo)', 'Nombre propio de una ciudad levítica en el territorio de Dan, repetidamente disputada por los filisteos. Sus seis ocurrencias abarcan dos ámbitos textuales: las listas de reparto y ciudades levíticas de Josué (19:44; 21:23) y las narraciones de asedio de 1 Reyes (15:27; 16:15, 17), donde dos golpes de estado ocurren entre las fuerzas israelitas que la sitian. Las variantes preposicionales no producen distinción semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89312, 'spa', 'Techo, azotea — La superficie plana superior de un edificio, parte integral de l', 'Techo, azotea — La superficie plana superior de un edificio, parte integral de la vida cotidiana en el antiguo Cercano Oriente. Se usaba para ocultarse (Rahab esconde a los espías, Jos 2:6), observación real (David ve a Betsabé, 2 S 11:2), conversación privada (Samuel y Saúl, 1 S 9:25), proclamación pública (2 S 16:22) y lamento (Isa 15:3; Jer 19:13). Deuteronomio 22:8 exige un pretil para seguridad. Se extiende también a la parte superior del altar del incienso (Ex 30:3; 37:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89334, 'spa', 'Gad (nombre propio', 'Gad (nombre propio: patriarca, tribu o profeta)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89340, 'spa', 'Reunirse en tropas', 'Agruparse o reunirse como grupo hostil, usado en Hitpael y Qal. Miqueas 5:1 ordena ''reúnete en tropas,'' dirigiéndose a una ciudad sitiada. Salmo 94:21 describe a los malvados confabulándose contra el justo. Jeremías 5:7 retrata a personas agolpándose hacia casas de prostitución. Conecta con la idea militar de formar una banda de asalto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89342, 'spa', 'Cortarse, lacerarse', 'Acción reflexiva de cortarse en el tronco Hitpael, que describe la laceración ritual del cuerpo. Deuteronomio 14:1 lo prohíbe entre los israelitas: ''no os haréis incisiones'' por los muertos. 1 Reyes 18:28 narra cómo los profetas de Baal se cortaban hasta que la sangre fluía. Jeremías 16:6, 41:5 y 47:5 lo asocian con ritos de duelo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89349, 'spa', 'Ribera u orilla fluvial', 'La ribera o terraplén de un río, siempre en contexto de desbordamiento o cruce en época de crecida. Jos 3:15 y 4:18 describen al Jordán desbordando todas sus riberas durante la cosecha, en el contexto del cruce milagroso. 1 Cr 12:16 recuerda a guerreros cruzando cuando el Jordán se desbordaba. Is 8:7 emplea la imagen metafóricamente: Asiria como el Éufrates inundando por todas sus riberas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89350, 'spa', 'Banda, tropa, partida de asalto — Una banda de hombres armados reunidos para inc', 'Banda, tropa, partida de asalto — Una banda de hombres armados reunidos para incursionar, saquear o realizar operaciones militares. La persecución de David contra la partida amalecita en Siclag ejemplifica el término (1 S 30:8-23). Recurrente en Reyes para bandas merodeadoras en las fronteras (2 R 5:2; 6:23; 13:20-21; 24:2). El juego de palabras en Gn 49:19 hace alusión al nombre de Gad. Usado figuradamente de las ''tropas'' hostiles de Dios en Job 19:12 y de bandas sacerdotales que cometen violencia en Oseas 6:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89375, 'spa', 'grande, considerable', 'Sentido adjetival nuclear: grande, considerable o significativo en tamaño, extensión, importancia o intensidad. Abarca magnitud física (''mar grande'', Nm 34:6), intensidad emocional (''gran temor'', Gn 15:12) y peso teológico (''gran nación'', Gn 12:2). El árabe عظيم y كبير, el español grande y el alemán groß convergen aquí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89379, 'spa', 'grandes obras, prodigios', 'Sustantivado en femenino plural (גְּדֹלוֹת): ''grandes cosas, grandes obras, prodigios''. Aparece en contextos doxológicos que celebran los actos incomprensibles de Dios (Job 5:9; 9:10; 37:5) y en el recuerdo deuteronómico de sus hazañas (Dt 10:21). El árabe عظائم refleja la misma formación de plural abstracto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89381, 'spa', 'mayor, primogénito', 'Sentido comparativo para ''mayor'' o ''de más edad'' en contextos de primogenitura o antigüedad. El árabe الكُبرَى marca específicamente al hermano mayor, al igual que el español el mayor. Prominente en las narrativas patriarcales: Esaú como el hijo mayor (Gn 27:1, 15, 42) y Lea como la hija mayor (Gn 29:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89382, 'spa', 'fuerte, intenso', 'Conjunto de usos contextualmente diferenciados que incluyen ''alta'' (referido a la voz, como en Is 36:13 y Gn 39:14), ''grande'' en la locución ''en judeo/hebreo'' (designación de idioma en Is 36:13) y marcadores de grado intensivo. Comparten el sentido raíz de magnitud aplicado al volumen sonoro o al énfasis (Esd 10:12; Pr 27:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89386, 'spa', 'nobles, grandes', 'Sustantivado en masculino plural o en constructo, designa ''nobles, grandes, dirigentes'': personas de alto rango o autoridad. Véase Jonás 3:7 (los grandes de Nínive) y 2 R 10:6, 11 (los magnates de Jezreel). El árabe عُظَماء y el coreano 귀인들 emplean términos propios para dignatarios, revelando el desplazamiento de cualidad a estatus social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89392, 'spa', 'ir en aumento', 'Uso verbal-progresivo o de infinitivo absoluto que expresa el proceso de crecer en magnitud y estatus. Atestiguado en las descripciones de la creciente grandeza de David (2 S 5:10; 1 Cr 11:9) y del ascenso de Mardoqueo (Est 9:4). El árabe وتعاظمًا capta el aspecto progresivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89422, 'spa', 'Grandeza, obras poderosas', 'Grandeza, magnificencia o majestad, usada tanto en sentido abstracto de la naturaleza incomparable de Dios (1 Cr 29:11; Sal 145:3, 6) como en sentido concreto de las obras poderosas que realiza en favor de su pueblo (2 S 7:21, 23; 1 Cr 17:19, 21). También se aplica al honor y rango humanos — la grandeza de Mardoqueo (Est 6:3; 10:2) y el esplendor desplegado por el rey Asuero (Est 1:4). La forma plural intensiva subraya hazañas extraordinarias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89433, 'spa', 'Ultrajes e injurias', 'Palabras de escarnio o insultos que aparecen tres veces en Isaías y Sofonías, siempre en paralelo con חֶרְפָּה («oprobio»). Isaías 43:28 lo vincula con חֵרֶם («destrucción»), Isaías 51:7 exhorta a los fieles a no temer estas injurias, y Sofonías 2:8 alude a las burlas de Moab. La raíz connota un discurso despectivo que deshonra activamente a su destinatario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89435, 'spa', 'Cría de cabra o cabrito (גְּדִי), típicamente especificado como ''cabrito de las ', 'Cría de cabra o cabrito (גְּדִי), típicamente especificado como ''cabrito de las cabras''. Aparece en contextos diversos: como elemento pastoral y culinario en las narrativas patriarcales (Gn 27:9, 16; 38:17, 20, 23), como sujeto de la prohibición dietética repetida tres veces contra cocer el cabrito en la leche de su madre (Éx 23:19; 34:26; Dt 14:21), y como ofrenda presentada ante el Señor (Jue 6:19; 13:15, 19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89446, 'spa', 'Término gentilicio para un miembro de la tribu de Gad (גָּדִי), usado tanto como', 'Término gentilicio para un miembro de la tribu de Gad (גָּדִי), usado tanto como adjetivo como sustantivo colectivo. Los gaditas se asentaron en Transjordania, recibiendo territorio desde Aroer hacia el norte (Dt 3:12, 16; Jos 12:6; 13:8). Figuran como guerreros feroces al servicio de David (1 Cr 12:8, 37) y en listas censales tribales (1 Cr 5:18, 26). El término marca la identidad tribal en contextos legales y de pacto también.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89457, 'spa', 'Parva o gavilla', 'Montón o pila de gavillas de grano cosechado. Éxodo 22:6 y Jueces 15:5 lo emparejan con קָמָה («grano en pie»), distinguiendo la parva ya segada del grano aún plantado. Job 5:26 lo usa en sentido figurado: morir en la vejez es como una gavilla recogida a su debido tiempo. El término resalta la abundancia reunida de la cosecha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89459, 'spa', 'Qal: crecer físicamente', 'Qal intransitivo que denota crecimiento y maduración física, dicho de niños y jóvenes. Concentrado en las narrativas de Génesis sobre los hijos de los patriarcas (Gn 21:8; 25:27), marca la transición de la infancia a la adultez. El español creció y el francés grandit preservan el sentido de desarrollo orgánico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89462, 'spa', 'Qal: hacerse grande', 'Qal dinámico: el proceso de hacerse grande en poder, riqueza o estatus, distinto de la mera maduración física. El siervo de Abraham informa que el Señor ha engrandecido a su amo (Gn 24:35); el Faraón dice a José ''solo en el trono seré mayor que tú'' (Gn 41:40).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89463, 'spa', 'Hifil/Hitpael: jactarse', 'Sentido reflexivo (Hifil reflexivo o Hitpael): engrandecerse a sí mismo, jactarse o actuar con arrogancia. Suele conllevar connotación negativa: el salmista lamenta a quienes ''se engrandecen contra mí'' (Sal 35:26; 55:12). El español se engrandecerá capta la exaltación autodirigida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89464, 'spa', 'Qal: ser grande, estativo', 'Qal estativo que expresa un estado de grandeza existente, no un proceso de llegar a serlo. Se usa en declaraciones de alabanza como ''Grande eres tú, oh Señor Dios'' (2 S 7:22) y ''Sea satisfecho el Señor'' (Sal 35:27). El español eres grande capta la cualidad descriptiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89465, 'spa', 'Piel: magnificar, exaltar', 'Piel declarativo-factitivo: magnificar, exaltar o engrandecer mediante acción deliberada. Dios promete a Abraham ''engrandeceré tu nombre'' (Gn 12:2) y Josué es magnificado ante Israel (Jos 3:7). Se distingue del Hifil en que enfatiza el honor conferido más que la acción realizada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89470, 'spa', 'Piel: criar hijos', 'Piel factitivo de crianza: criar, nutrir o educar hijos desde la infancia hasta la madurez. Isaías 1:2 lo usa con fuerza: ''Crié hijos y los engrandecí, y ellos se rebelaron contra mí''. También se aplica a dejar crecer el cabello (Nm 6:5). El español crié/crió confirma el sentido de cuidado parental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89474, 'spa', 'Hifil: engrandecer, hacer proezas', 'Causativo Hifil: engrandecer o realizar grandes obras. Se usa cuando Dios hace grandes cosas por Israel (1 S 12:24) y magnifica su fidelidad al pacto (Gn 19:19). El patrón multilingüe lo traduce consistentemente como causación activa de grandeza: español engrandeció, alemán gross-machen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89502, 'spa', 'crecido, maduro', 'Uso participial o adjetival que describe algo completamente desarrollado o maduro, como en Salmo 144:12 donde los hijos se comparan con plantas ''crecidas'' en su juventud. El español crecidas y el alemán wurde-gross confirman un estado resultativo: el fruto consumado del proceso de crecimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89534, 'spa', 'grande de (atributivo)', 'Construcción atributiva en Nahúm 1:3, donde la palabra funciona como parte de una locución compuesta que describe grandeza de poder. El español ''y grande de'' y el francés ''et grandir'' sugieren un sentido adjetival-estativo que modifica atributos divinos, expresando magnitud o intensidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89548, 'spa', 'Creciendo progresivamente', 'Que va haciéndose grande, creciendo progresivamente en tamaño, riqueza o estatura. En Gn 26:13 Isaac ''iba engrandeciéndose'' (הָלוֹךְ וְגָדֵל) en una vívida construcción progresiva. En 1 S 2:26 el niño Samuel ''seguía creciendo'' en estatura y en favor divino y humano. En 2 Cr 17:12 Josafat igualmente ''se engrandeció cada vez más''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89549, 'spa', 'Grandeza, magnitud', 'Grandeza o magnitud que abarca el poder divino, el esplendor real y la enormidad física, pero también, cuando se califica con ''corazón'', el orgullo y la arrogancia desmedida. Moisés apela a la grandeza de la misericordia de Dios (Nm 14:19) y de su poder (Dt 3:24; 9:26), mientras que la declaración litúrgica de Deuteronomio 32:3 atribuye grandeza al nombre de Dios. Ezequiel la aplica al cedro imponente que simboliza al faraón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89562, 'spa', 'Nombre propio Guidel', 'El nombre propio Guidel, que identifica a los cabezas de dos familias de siervos postexílicos. La familia de netineos aparece en Esd 2:47 / Neh 7:49; la familia de siervos salomónicos en Esd 2:56 / Neh 7:58. El nombre probablemente portaba un sentido teofórico — que Dios ''engrandeció'' al portador o a su linaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89563, 'spa', 'Gedalías (nombre propio)', 'Nombre propio Gedalías (''YHWH es grande''), que designa principalmente a Gedalías hijo de Ahicam, el gobernador de Judá nombrado por Babilonia, cuyo asesinato se narra en Jeremías 40-41 y precipitó la huida del remanente a Egipto. El mismo nombre corresponde a al menos otros dos personajes bíblicos: un antepasado de Sofonías (Sof 1:1) y un sacerdote en Esdras 10:18.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89565, 'spa', 'Nombre propio Gedalyahu, portado por al menos tres individuos', 'Nombre propio Gedalyahu, portado por al menos tres individuos. El gobernador de Judá (2 R 25:22-25; Jer 39:14–43:6) concentra la mayoría de las apariciones; su asesinato se conmemora en el Ayuno de Gedalías. Un segundo Gedalyahu fue un oficial jerosolimitano en tiempos de Jeremías (Jer 38:1), y un tercero sirvió entre los músicos levíticos bajo David (1 Cr 25:3, 9). En español se adapta como «Gedalías».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89569, 'spa', 'Sentido activo Qal y Piel', 'Sentido activo Qal y Piel: talar, cortar o hacer pedazos. El sujeto ejerce fuerza destructiva contra árboles, objetos cúlticos u objetivos metafóricos. Deuteronomio ordena a Israel «cortar» las Aserás de las naciones (Dt 7:5; 12:3), y reyes fieles como Asá y Ezequías lo cumplen (2 Cr 14:3; 31:1; 34:4, 7). Zacarías «cortó en dos» sus cayados llamados Gracia y Unión (Zac 11:10, 14), simbolizando la ruptura de las alianzas divinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89573, 'spa', 'Sentido pasivo Nifal', 'Sentido pasivo Nifal: ser talado, ser cortado, ser destruido — típicamente como imagen del juicio divino sobre los soberbios o poderosos. Isaías 9:10 declara que los sicómoros «han sido talados» pero serán reemplazados por cedros; Isaías 14:12 pregunta cómo el rey de Babilonia «ha sido derribado» a tierra — una de las imágenes más dramáticas de caída del cielo en la Biblia. Jeremías 48:25 anuncia que el cuerno de Moab «ha sido cortado».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89588, 'spa', 'Gedeón (nombre propio) — El nombre propio del quinto juez mayor de Israel, que a', 'Gedeón (nombre propio) — El nombre propio del quinto juez mayor de Israel, que aparece en las 39 ocurrencias dentro de Jueces 6-8. Las traducciones multilingües preservan la fonología hebrea con mínima adaptación — en español ''Gedeón'', en francés ''Gédéon'', en alemán e inglés ''Gideon'' — reflejando la amplia familiaridad del nombre a través del relato bíblico del vellón, los 300 guerreros y la derrota de Madián.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89593, 'spa', 'Nombre propio: Gedeoni', 'Nombre personal que identifica a un benjamita, padre de Abidán, el príncipe tribal de Benjamín durante el período del desierto. Las cinco ocurrencias aparecen en Números dentro de la fórmula estereotipada ''Abidán hijo de Gedeoni'': en el censo (1:11), la disposición del campamento (2:22), las ofrendas de dedicación del tabernáculo (7:60, 65) y el orden de marcha (10:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89594, 'spa', 'Blasfemar, injuriar', 'Injuriar o blasfemar, hablando con desprecio contra Dios o ultrajando al prójimo. En Números 15:30, el pecador deliberado ''blasfema contra el SEÑOR'' (מְגַדֵּף, participio) y debe ser extirpado. La arrogancia de Senaquerib es condenada con este verbo en 2 Reyes 19:6, 22 y su paralelo Isaías 37:6, 23, emparejado con חֵרֵף (''afrentar''). Entre personas, el Salmo 44:17 describe la voz de quien injuria y blasfema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89600, 'spa', 'Encerrar, bloquear, cercar', 'Encerrar, bloquear, cercar. Bloquear o confinar a alguien encerrando con muros su camino — una poderosa metáfora de la restricción divina. Dios ''cerca'' el camino de Job para que no pueda pasar (Job 19:8) y encierra al hombre sufriente de Lamentaciones 3:7, 9. El desplazamiento semántico de construir a confinar refleja la versatilidad de esta raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89601, 'spa', 'Construir un muro', 'Construir un muro. Construir o erigir un muro de piedra, incluyendo el participio sustantivado ''constructor de muros, albañil'' como oficio reconocido. Los albañiles del Templo en 2 Reyes 12:13 y 22:6 son llamados godrim, y Miqueas 7:11 vislumbra un día para edificar muros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89605, 'spa', 'Reparar una brecha', 'Reparar una brecha. Reparar o cerrar una brecha en un muro existente, restaurando lo que se ha desmoronado. El ''reparador de portillos'' de Isaías (58:12) y el cierre de las brechas en la cabaña caída de David (Am 9:11) emplean este sentido. Se destaca el matiz restaurativo frente al de construcción original.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89611, 'spa', 'Gedor (nombre propio)', 'El nombre propio Gedor, que funciona como topónimo y como antropónimo. Como lugar: una ciudad en la serranía de Judá (Jos 15:58), posiblemente también la localidad mencionada en 1 Crónicas 4:39 (aunque la LXX y muchos estudiosos leen ''Gerar''). Como nombres personales en las genealogías del Cronista: un descendiente de Judá por medio de Penuel (1 Cr 4:4) y Jered (1 Cr 4:18), probablemente ancestros epónimos de la ciudad. Un benjaminita de Gabaón también lleva este nombre (1 Cr 8:31; 9:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89614, 'spa', 'Muro, cerca o recinto de piedra construido como límite o barrera, especialmente ', 'Muro, cerca o recinto de piedra construido como límite o barrera, especialmente en torno a terrenos agrícolas. Aparece en contextos tanto literales como figurados: el muro del camino estrecho que atrapa al asna de Balaam (Nm 22:24), los muros del viñedo que Dios derriba como juicio (Sal 80:12; Is 5:5), el muro protector que Dios concede en la tierra restaurada (Esd 9:9) y la cerca tambaleante como imagen de vulnerabilidad (Sal 62:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89621, 'spa', 'Redil o corral para ganado — recinto amurallado para resguardar rebaños', 'Redil o corral para ganado — recinto amurallado para resguardar rebaños. Predomina en Números 32 (vv. 16, 24, 36), donde las tribus transjordanas construyen corrales para su abundante ganado antes de cruzar a Canaán. También en 1 Samuel 24:3, donde Saúl entra en una cueva junto a los rediles, y en Sofonías 2:6, donde la costa se convierte en pastizales con corrales de ovejas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89622, 'spa', 'Muro, cerca o seto que funciona como límite o defensa', 'Muro, cerca o seto que funciona como límite o defensa. El Salmo 89:40 emplea el plural con sufijo posesivo («sus muros») para lamentar que Dios desmantele las defensas reales. Nahúm 3:17 retrata a los oficiales de Nínive como langostas posadas en los setos durante el frío. Jeremías 49:3 habla de vagar entre cercados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89625, 'spa', 'Gederá como nombre propio — ciudad en la Sefelá (tierras bajas) de Judá, mencion', 'Gederá como nombre propio — ciudad en la Sefelá (tierras bajas) de Judá, mencionada en 1 Crónicas 4:23 entre los asentamientos donde los alfareros servían al rey. El nombre conserva el vínculo etimológico con «recinto», pues la ciudad probablemente se llamó así por su carácter amurallado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89639, 'spa', 'Inclinarse o tenderse', 'Agacharse, inclinarse o tenderse sobre algo en intercesión profética u obra milagrosa. En 1 Reyes 18:42, Elías se inclinó hasta el suelo (con ''hacia la tierra'') en oración por lluvia. En 2 Reyes 4:34-35, Eliseo se tendió sobre el niño muerto (con ''sobre él''), en paralelo con ''se acostó sobre'' en el versículo 34.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89640, 'spa', 'Espalda (rechazo)', 'La espalda del cuerpo, usada exclusivamente en la expresión idiomática ''echar tras la espalda'' para expresar rechazo o desprecio. Las tres apariciones siguen el mismo patrón: ''echar (הִשְׁלִיךְ) tras (אַחֲרֵי) tu/su espalda (גֵּו)''. Los objetos echados tras la espalda son: Dios mismo (1 R 14:9, Ez 23:35) y la ley de Dios (Neh 9:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89641, 'spa', 'Medio, dentro, hacia', 'Denota interioridad espacial o contención, siempre regido por una preposición. Con beth marca ubicación estática (''en medio de'', Dn 3:25; Esd 5:7), con lamed indica movimiento direccional hacia un espacio (''hacia dentro'', Dn 3:6, 11, 15), y con min señala movimiento desde el interior (''de en medio de'', Dn 3:26). La evidencia de traducción en diversos idiomas converge en un único concepto espacial-relacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89645, 'spa', 'Espalda (parte corporal)', 'La espalda del cuerpo humano, empleada tanto en sentido literal (como parte golpeada con vara o látigo) como figurado (como superficie pisoteada o algo oculto ''detrás''). Los tres pasajes de Proverbios (10:13; 19:29; 26:3) establecen el sentido concreto de la espalda que recibe castigo corporal. Isaías 50:6 extiende esto al sufrimiento voluntario del Siervo, mientras que Isa 38:17 despliega la expresión idiomática de arrojar los pecados tras la espalda de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89653, 'spa', 'Nombre propio que identifica', 'Nombre propio que identifica: (a) un descendiente de Rubén en la genealogía del Cronista (1 Cr 5:4), y (b) el gobernante escatológico «de la tierra de Magog, príncipe soberano de Mesec y Tubal» (Ez 38:2-3), quien encabeza una vasta coalición del extremo norte contra el Israel restaurado, solo para ser destruido por la intervención directa de Dios (Ez 38:18-23; 39:1-15). La figura ezequieliana se convierte en paradigma del enemigo final del pueblo de Dios, retomada en Apocalipsis 20:8.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89655, 'spa', 'Asaltar militarmente', 'Asaltar, atacar o invadir con fuerza militar. Génesis 49:19 lo emplea tres veces con un juego de palabras: ''una tropa lo asaltará (יְגוּדֶנּוּ), pero él asaltará (יָגֻד) su retaguardia''. Habacuc 3:16 habla de un pueblo que nos atacará (יְגוּדֶנּוּ). Denota una incursión rápida y agresiva más que un asedio prolongado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89657, 'spa', 'Soberbia o exaltación', 'Soberbia, altivez arrogante o posiblemente un grito de exaltación. En Job 33:17 y Jeremías 13:17 significa claramente soberbia que debe ser ocultada o lamentada. Job 22:29 es debatido: algunas traducciones lo leen como exclamación ''¡Arriba!'', mientras otras lo interpretan como soberbia. Abarca tanto el orgullo pecaminoso como la elevación en sentido general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89661, 'spa', 'Gozán (topónimo)', 'Nombre geográfico de una ciudad y distrito mesopotámico sobre el río Habor donde los israelitas del norte fueron reasentados tras la conquista asiria. En 2 Re 17:6 y 18:11 designa el destino de la deportación; 1 Cr 5:26 lo incluye entre los lugares de exilio. En 2 Re 19:12 (= Is 37:12) se cita como nación cuyos dioses fueron impotentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89662, 'spa', 'naciones, pueblos (plural)', 'Sentido plural o colectivo: ''naciones, pueblos'' -- el uso dominante (466 apariciones), que se refiere típicamente a múltiples pueblos extranjeros o a todas las naciones de la tierra. Suele conllevar una fuerza contrastiva frente a Israel: ''todas las naciones que el Señor tu Dios pone delante de ti'' (Dt 7:1). La traducción constante como las naciones confirma su carácter de plural genérico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89665, 'spa', 'nación, pueblo (singular)', 'Sentido singular: ''una nación, un pueblo'' -- una entidad política o étnica individual (98 apariciones). Puede designar a Israel mismo (''gran nación'', Gn 12:2; ''nación santa'', Éx 19:6) o a cualquier otro pueblo (''una nación que no conoces'', Dt 28:36). Pasajes teológicos clave incluyen la promesa de Dios a Abraham y la vocación de Israel como pueblo apartado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89703, 'spa', 'Goyim (nombre propio)', 'Aparición problemática en Josué 12:23, donde גּוֹיִם parece funcionar como nombre propio o designación geográfica -- ''el rey de Goyim en Gilgal'' -- más que como sustantivo común. La evidencia multilingüe está dividida: el inglés y el francés traducen ''naciones'', pero el español translitéra como Goyim, tratándolo como topónimo o etnónimo. Probablemente se refiere a la misma entidad que Goyim en Génesis 14:1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89707, 'spa', 'Cuerpo, cadáver', 'El cuerpo físico en toda su amplitud: vivo, muerto o visionario. Aplicado a los vivos, designa la estructura corporal en su totalidad (Gn 47:18; Dn 10:6; Ez 1:11, 23). Aplicado a los muertos, significa cadáver o cuerpo sin vida, como el de Saúl en el muro de Bet-sán (1 S 31:10, 12) o los muertos amontonados en el campo de batalla (Sal 110:6; Nah 3:3). Las traducciones en español reflejan esta dualidad entre vivo y muerto con ''cuerpo'' y ''cadáver''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89719, 'spa', 'Exilio, cautiverio, desterrados — Abarca tanto el estado abstracto de exilio com', 'Exilio, cautiverio, desterrados — Abarca tanto el estado abstracto de exilio como la comunidad concreta de deportados. En expresiones como ''ir al exilio'' (Jer 48:11; Ez 12:11) denota la condición; como ''la asamblea de los desterrados'' (Esd 10:8) se refiere al pueblo mismo. Los términos multilingües acentúan diferentes facetas de este doble uso: en español ''cautiverio'' subraya la sujeción, en francés ''exil'' destaca el desarraigo, en alemán ''Verbannung'' enfatiza la expulsión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89733, 'spa', 'Golán (ciudad de refugio)', 'Nombre propio Golán, que designa una ciudad levítica de refugio en la región de Basán, en Manasés oriental. Moisés la estableció como refugio para el homicida involuntario (Dt 4:43), y figura tanto entre las seis ciudades de refugio (Jos 20:8) como entre las ciudades levíticas asignadas a los gersonitas (Jos 21:27; 1 Cr 6:71). La variante Ketiv/Qere galon/golan es un asunto puramente ortográfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89736, 'spa', 'Nombre propio Guni', 'Nombre personal גּוּנִי que designa a un ancestro tribal neftalita y a un gadita. En Gn 46:24 y 1 Cr 7:13 aparece como hijo de Neftalí; Nm 26:48 deriva de él el clan gunita. Un Guni distinto en 1 Cr 5:15 pertenece a la tribu de Gad. Las traducciones al español mantienen la forma «Guni» de manera consistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89738, 'spa', 'Expirar, exhalar el último aliento, perecer — marcando el momento preciso en que', 'Expirar, exhalar el último aliento, perecer — marcando el momento preciso en que la vida se extingue. Restringido a la fuente Sacerdotal y a los textos poéticos, este verbo dignifica la muerte de los patriarcas: Abraham (Gn 25:8), Ismael (Gn 25:17), Isaac (Gn 35:29) y Jacob (Gn 49:33) «expiran» en fórmulas solemnes de defunción. En el relato del Diluvio describe el perecer universal (Gn 6:17; 7:21). En la poesía sapiencial expresa la fragilidad de la vida mortal: cuando Dios retira su aliento, las criaturas expiran y vuelven al polvo (Job 34:15; Sal 104:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89762, 'spa', 'Qal ptcp', 'Qal ptcp: forastero, residente extranjero');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89763, 'spa', 'Qal', 'Qal: peregrinar como extranjero');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89767, 'spa', 'Qal', 'Qal: morar, alojarse con');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89777, 'spa', 'Qal ptcp', 'Qal ptcp: huésped, alojado');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89806, 'spa', 'Atacar, provocar contienda', 'Provocar contienda, atacar o asaltar. En los Salmos de lamento, David describe enemigos que ''se reúnen'' o ''atacan'' — yaguru en Sal 56:6 (acechando y vigilando sus pasos), Sal 59:3 (congregándose contra él sin causa) y Sal 140:2 (tramando guerras). Isaías 54:15 ofrece una garantía teológica: גּוֹר יָגוּר, un infinitivo absoluto enfático que asegura que todo agresor caerá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89807, 'spa', 'Lacerarse (Hitpael)', 'Lacerarse o cortarse a sí mismo (Hitpael reflexivo), describiendo la automutilación ritual en contextos de éxtasis o duelo. La única atestación en Oseas 7:14, yitgoraru, retrata a israelitas que ''se laceran por el grano y el mosto'', adoptando prácticas rituales cananeas en lugar de clamar genuinamente a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89812, 'spa', 'Temer, tener miedo o sentir reverencia — expresa temor reverencial ante Dios o t', 'Temer, tener miedo o sentir reverencia — expresa temor reverencial ante Dios o terror existencial ante un poder abrumador. Moab «tuvo gran temor» de Israel (Nm 22:3); Moisés exhorta a los jueces a no «tener miedo de ningún hombre» (Dt 1:17); el salmista convoca a todos los habitantes de la tierra a «temblar» ante el Señor (Sal 33:8; 22:24). Deuteronomio 18:22 asegura a Israel que no debe temer a un profeta cuya palabra no se cumpla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89822, 'spa', 'Cachorro de león', 'Cachorro o cría, típicamente de león, usado en metáforas poéticas y proféticas. La bendición de Jacob llama a Judá ''cachorro de león'' (Gn 49:9, גּוּר אַרְיֵה), evocando fortaleza tribal y destino real. Moisés bendice a Dan como ''cachorro de león que salta desde Basán'' (Dt 33:22). En Ezequiel 19:2-5, una leona cría a sus cachorros (גּוּרֶיהָ) — alegoría de la casa real de Judá — y uno de ellos se convierte en león joven (כְּפִיר).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89830, 'spa', 'suerte (objeto echado para decisiones)', 'suerte (objeto echado para decisiones)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89834, 'spa', 'porción asignada por suerte', 'porción asignada por suerte');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89853, 'spa', 'Esquileo o vellón', 'Esquileo o vellón — la lana cortada de las ovejas, considerada producto valioso. En Dt 18:4 se enumera junto al grano, el vino y el aceite como porción sacerdotal: «las primicias del vellón de tus ovejas». En Job 31:20 el vellón abriga al necesitado, sirviendo como medida de la compasión del justo. Los cognados arameo gizza y asirio gizzu confirman el sentido central de lana trasquilada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89857, 'spa', 'Vellón de lana', 'Vellón de lana, el manto esquilado de una oveja usado como objeto físico en una prueba de la voluntad divina. Las siete apariciones se concentran en Jueces 6:37-40, donde Gedeón coloca el vellón (גִּזַּת צֶמֶר) sobre la era durante la noche, pidiendo a Dios que lo humedezca o lo seque como confirmación. En español se traduce consistentemente como ''vellón''. La forma constructa גִּזַּת aparece ligada a צֶמֶר (lana).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89861, 'spa', 'Esquilar, cortar', 'Esquilar ovejas o cortar lana en un evento agrícola comunitario. Las ocasiones de esquila sirven como momentos narrativos clave: el robo de Raquel durante la esquila de Labán (Gn 31:19), el encuentro de Judá con Tamar (Gn 38:12-13), el conflicto de Nabal con David (1 S 25:2-11) y el asesinato de Amnón por Absalón (2 S 13:23-24). El uso teológicamente más significativo es Isaías 53:7, el siervo que enmudece ''ante sus trasquiladores''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89874, 'spa', 'Piedra cortada, labrada o escuadrada en bloques regulares para fines constructiv', 'Piedra cortada, labrada o escuadrada en bloques regulares para fines constructivos, especialmente arquitectura monumental. Se distingue de la piedra tosca del campo por el trabajo de cantería y tallado. Central en los proyectos de construcción de Salomón (1 R 5:17; 6:36; 7:9-12), prohibida para la construcción del altar por mandato divino (Éx 20:25) y empleada como imagen profética de autosuficiencia orgullosa (Is 9:10) y de opresión que no será disfrutada (Am 5:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89881, 'spa', 'Arrebatar, robar o quitar por la fuerza, implicando la toma violenta de bienes, ', 'Arrebatar, robar o quitar por la fuerza, implicando la toma violenta de bienes, ganado o personas. Abraham confronta a Abimelec por un pozo que le fue arrebatado (Gn 21:25). Levítico 5:23 y 19:13 legislan la restitución de lo que se ha tomado. Jueces 21:23 describe a los benjaminitas arrebatando esposas. En la denuncia profética, Ezequiel 18:7, 12, 16, 18 y Miqueas 3:2 usan este verbo para condenar a gobernantes opresores. Job 20:19 y 24:2, 9 lo emplean para describir vívidamente cómo los malvados arrancan casas, linderos e incluso infantes lactantes a los pobres.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89906, 'spa', 'Robo o saqueo', 'Robo o saqueo — la toma forzosa de bienes ajenos o el botín mismo. Se usa en contextos legales (Lv 6:2, exigiendo confesión y restitución), advertencias sapienciales (Sal 62:10, emparejado con la opresión), y denuncias proféticas de injusticia (Is 61:8; Ez 22:29), abarcando tanto el acto abstracto como los bienes concretos arrebatados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89908, 'spa', 'Robo, despojo, botín', 'Robo, despojo o bienes arrebatados por la violencia: el sustantivo abstracto/concreto de la raíz g-z-l. En contextos legales (Lv 6:4), designa los bienes robados que deben ser restituidos con penalidad. En el catecismo de justicia de Ezequiel (18:7, 12, 16), cometer gezelah es marca diagnóstica de maldad. Isaías 3:14 lo emplea como acusación profética: el despojo del pobre hallado en las casas de los dirigentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89913, 'spa', 'Langosta cortadora', 'Un tipo de langosta caracterizada por cortar y devorar la vegetación, que aparece tres veces en oráculos proféticos de juicio. Joel 1:4 y 2:25 la enumeran entre cuatro especies de langosta, mientras que Amós 4:9 la usa sola para describir la plaga devoradora. Su nombre deriva de la raíz que significa ''cortar'', subrayando su acción destructiva sobre los cultivos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89915, 'spa', 'Tronco o cepa', 'El tronco, cepa o tocón de un árbol, con usos tanto literales como figurados. Job 14:8 lo empareja con «raíz» (שֹׁרֶשׁ) en paralelismo: aunque la raíz envejezca y el tronco muera en tierra, hay esperanza de renovación. Isaías 11:1 lo emplea mesiánicamente: «un retoño del tronco de Jesé». Isaías 40:24 describe plantas cuyo tallo apenas echa raíz antes de ser barridas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89916, 'spa', 'Cortar, dividir', 'Abarca el significado físico primario de cortar, dividir o separar objetos y personas. En Qal describe cortar leña (2 R 6:4), dividir a un niño (1 R 3:25) y la dramática partición del mar Rojo ''en partes'' (Sal 136:13, donde el español traduce ''Al que dividió''). El Nifal pasivo transmite ser cortado de la comunidad o de la vida, como en el lamento del Salmo 88:5 y la exclusión del rey leproso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89918, 'spa', 'Decretar, determinar', 'Extensión metafórica influida por el arameo donde ''cortar'' se convierte en ''decretar'' o ''determinar'', tratando una decisión como algo tallado o grabado. Job 22:28 promete que lo que uno decrete será establecido (en español ''decretarás''), mientras que Ester 2:1 usa el Nifal para informar lo que ''fue decretado'' contra Vasti. El paso del corte físico al pronunciamiento autoritativo refleja un desarrollo semántico compartido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89927, 'spa', 'Astrólogo, adivino', 'Adivino o astrólogo profesional, derivado del participio Qal usado como sustantivo: literalmente, aquel que ''corta'' o ''determina'' mediante la lectura de señales celestes. Las cuatro apariciones pertenecen a listas de especialistas de la corte babilónica (Dan 2:27; 4:7; 5:7, 11). El español distingue entre ''astrólogos'' y ''adivinos'', lo que refleja el rango interpretativo de este único término arameo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89928, 'spa', 'Ser cortado, tallado', 'Sentido pasivo/reflexivo del Hitpael: ser cortado o tallado de una masa mayor, describiendo una separación física sin intervención humana. Ambas apariciones representan la piedra milagrosa en la visión de Nabucodonosor, cortada de un monte sin manos (Dan 2:34, 45). La voz pasiva enfatiza la acción divina en contraste con la agencia humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89932, 'spa', 'Gezer (topónimo)', 'La ciudad-estado fortificada de Gezer (Tell Jezer), situada en el camino entre Jope y Jerusalén, controlando un paso clave desde la llanura costera hacia las tierras altas. Sus 15 apariciones abarcan las narrativas de la conquista de Josué, las listas de ciudades levíticas, las batallas de David contra los filisteos y los proyectos de construcción real de Salomón. Las traducciones en diversos idiomas mantienen consistentemente el topónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89936, 'spa', 'Área separada', 'El recinto separado o patio adjunto al templo visionario de Ezequiel, término arquitectónico para un espacio abierto demarcado. Aparece en Ezequiel 41:12-15 y 42:1, 10, 13, designando el área ''cortada'' o apartada detrás y a los lados del templo propiamente dicho. Las traducciones al español como ''patio separado'' interpretan correctamente este espacio como un recinto abierto delimitado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89938, 'spa', 'Forma, figura', 'Forma pulida, figura o belleza de la apariencia corporal. Lamentaciones 4:7 describe a los príncipes de Jerusalén: ''su forma era como el zafiro,'' evocando una belleza esculpida o semejante a una gema. El sentido deriva de la raíz que significa cortar o tallar, extendido a la idea de algo finamente moldeado. Se distingue del uso arquitectónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89943, 'spa', 'Brasa, ascua ardiente', 'Brasa, ascua ardiente: carbón vivo e incandescente que aparece en contextos sacrificiales, teofánicos y metafóricos. El sumo sacerdote llena su incensario con גַּחֲלֵי־אֵשׁ (''brasas de fuego'') del altar en el Día de la Expiación (Lev 16:12). En la poesía teofánica, brasas de fuego arden ante la presencia de Dios (2 Sam 22:9, 13 = Sal 18:8, 12-13). La visión inaugural de Ezequiel compara a las criaturas vivientes con brasas ardientes (Ez 1:13; 10:2). Proverbios emplea la imagen tanto literalmente como en sentido proverbial (Prov 6:28; 26:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89957, 'spa', 'valle, barranco', 'valle, barranco');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89981, 'spa', 'Tendón, nervio', 'Tendón o nervio, el tejido fibroso conectivo que une músculo con hueso. Usado anatómicamente en Job 10:11 junto a piel, carne y huesos como estructura del cuerpo humano, y en Ezequiel 37:6,8 en la visión de los huesos secos reconstituidos con tendones y carne. El ''tendón de la cadera'' (גִּיד הַנָּשֶׁה) en Génesis 32:32 se refiere específicamente al tendón ciático desplazado durante la lucha de Jacob.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89987, 'spa', 'Brotar, irrumpir', 'Brotar o irrumpir con fuerza repentina, aplicado tanto a la erupción intransitiva (agua, ejércitos) como a la extracción transitiva (un niño del vientre). Job 40:23 describe un río que surge; Job 38:8 presenta el mar brotando del vientre cósmico. Salmo 22:9 pasa al plano personal: Dios sacó al salmista al nacer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89995, 'spa', 'Gihón', 'Nombre propio que designa dos fuentes de agua: (1) uno de los cuatro ríos del Edén (Gn 2:13), cuyo curso por «la tierra de Cus» ha generado siglos de debate geográfico, y (2) el manantial cerca de Jerusalén, donde Salomón fue ungido rey (1 R 1:33, 38, 45) y cuyas aguas Ezequías redirigieron mediante un túnel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (89999, 'spa', 'Giezi', 'Giezi: el siervo personal del profeta Eliseo, quien servía como intermediario (2 R 4:12), pero fue castigado con lepra tras obtener engañosamente los regalos que Eliseo había rechazado de Naamán (2 R 5:20-27). Las doce apariciones del nombre designan a este único individuo. Las traducciones al español (Giezi), francés (Guehazi) y alemán (Gehasi) confirman un solo referente en todos los contextos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90002, 'spa', 'Regocijarse, alegrarse — El sentido verbal central', 'Regocijarse, alegrarse — El sentido verbal central: regocijarse, alegrarse, exultar. Casi siempre aparece junto a שָׂמַח o en contextos de adoración — ''Alégrense los cielos'' (Sal 96:11), ''Alégrate mucho, hija de Sion'' (Zac 9:9). Las glosas multilingües eligen consistentemente términos intensos: en español ''gozarse'', en francés ''exulter'', señalando un gozo demostrativo y exuberante más que simple contentamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90013, 'spa', 'Temblar (sentido disputado) — Una única ocurrencia disputada en Oseas 10', 'Temblar (sentido disputado) — Una única ocurrencia disputada en Oseas 10:5, donde el contexto sugiere temor tembloroso en lugar de gozo. La ambigüedad probablemente surge de una inversión irónica profética: lo que era gozo de adoración por el becerro de oro se convierte en angustia temerosa ante su remoción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90023, 'spa', 'Regocijo (nominal/adverbial) — El infinitivo absoluto usado adverbialmente o nom', 'Regocijo (nominal/adverbial) — El infinitivo absoluto usado adverbialmente o nominalmente para expresar la manera o el acto de regocijarse, como en Proverbios 23:24 donde el padre ''se gozará grandemente'' (גִּיל יָגִיל). El español lo traduce como el gerundio ''regocijando'', resaltando su función intensificadora dentro del sistema verbal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90038, 'spa', 'Regocijo, exultación', 'Regocijo o exultación como cualidad abstracta: un gozo intenso, frecuentemente comunitario, asociado con la adoración, la cosecha o la celebración del pacto. Las traducciones multilingües convergen en ''regocijo/gozo'' (español), ''rejoicing/gladness'' (inglés), ''allégresse/joie'' (francés), apuntando todas a una alegría elevada y festiva. Típicamente se presenta en paralelo con שִׂמְחָה (Sal 45:15; Is 16:10; Jl 1:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90050, 'spa', 'Montón, pila de piedras — Montones o pilas que aparecen en múltiples contextos', 'Montón, pila de piedras — Montones o pilas que aparecen en múltiples contextos: olas en Éxodo 15:8, montones de grano en contextos agrícolas, o túmulos funerarios. La flexibilidad de la palabra permite describir cualquier cosa amontonada o acumulada. La imagen unificadora es la acumulación vertical, ya sea natural (olas) o hecha por el hombre (montones en la era, ruinas).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90051, 'spa', 'Ola, oleaje — Una ola u oleaje del mar, usada tanto literalmente para las mareja', 'Ola, oleaje — Una ola u oleaje del mar, usada tanto literalmente para las marejadas oceánicas como figuradamente para inundaciones abrumadoras de tribulación o poder divino. Dios pone un límite a las olas orgullosas en Job 38:11; el salmista clama que ''todas tus ondas han pasado sobre mí'' (Sal 42:7); y el Salmo 89:9 alaba a Dios que ''domina la braveza del mar y apacigua sus olas''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90062, 'spa', 'Fuente, manantial — Un manantial o fuente de agua, atestiguado una vez en Cantar', 'Fuente, manantial — Un manantial o fuente de agua, atestiguado una vez en Cantares 4:12: ''huerto cerrado eres, hermana mía, esposa; fuente cerrada, fuente sellada.'' La amada es comparada con un גַּל נָעוּל — una fuente oculta de agua viva. Todos los idiomas de destino emplean vocabulario de manantial, confirmando un sentido léxico plenamente distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90071, 'spa', 'Gilboa', 'La cadena montañosa donde Saúl y sus hijos murieron combatiendo contra los filisteos (1 Samuel 31; 2 Samuel 1). Todos los idiomas conservan el nombre propio mediante transliteración (Gilboa/Guilboa), práctica estándar para la geografía bíblica. La maldición poética de David convirtió a Gilboa en sinónimo de aridez y tragedia en la memoria israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90075, 'spa', 'Rueda, mecanismo de ruedas', 'Rueda, mecanismo de ruedas: una rueda o conjunto de ruedas, referido a las ruedas de carros de guerra o al mecanismo giratorio en la visión de Ezequiel. Isaías 5:28 y Jeremías 47:3 describen ruedas de carro cuyo estruendo anuncia un avance militar. En Ezequiel 10:2, 6, 13, el galgal es el mecanismo giratorio junto a los querubines, y en Eclesiastés 12:6 es la rueda del pozo, parte de la imaginería sobre el envejecimiento y la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90078, 'spa', 'Torbellino, polvo arremolinado', 'Torbellino, polvo arremolinado: torbellino o polvo y tamo arremolinados por el viento, usado en un lenguaje figurado vívido para describir cómo Dios dispersa a los enemigos. En el Salmo 83:13, el salmista ruega: ''Hazlos como el torbellino (galgal), como la paja ante el viento,'' e Isaías 17:13 emplea la misma imagen para las naciones que huyen ante la reprensión divina. El Salmo 77:18 sitúa el trueno de Dios ''en el torbellino,'' como vehículo de teofanía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90086, 'spa', 'Gilgal (nombre de lugar) — Nombre propio (principalmente el sitio del valle del ', 'Gilgal (nombre de lugar) — Nombre propio (principalmente el sitio del valle del Jordán) que significa ''círculo'', probablemente de piedras conmemorativas erigidas por Josué (Josué 4:19-20). Todas las lenguas transliteran Gilgal sin cambios, reconociendo su importancia como sitio bíblico mayor. La etimología conecta con la raíz hebrea ''rodar'', que Josué 5:9 aprovecha en un juego de palabras: ''He quitado de vosotros el oprobio de Egipto.'' Múltiples Gilgales aparecen en la geografía bíblica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90093, 'spa', 'Cabeza, individuo (unidad de conteo)', 'Cabeza, individuo (unidad de conteo): el cráneo en contextos militares y de ejecución. Jueces, Samuel, Reyes y Crónicas lo emplean al describir heridas mortales en la cabeza o la toma de trofeos (cráneos enemigos exhibidos en templos). El cognado arameo dio origen a ''Gólgota'' en los Evangelios. Las traducciones coinciden en ''cráneo'' en todos los idiomas, ya que la especificidad anatómica (hueso, no carne) es importante para comprender la violencia descrita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90094, 'spa', 'Cráneo (anatómico)', 'Cráneo (anatómico): el cráneo o bóveda craneal en sentido literal. En Jueces 9:53, una mujer fractura el cráneo de Abimelec con una piedra de molino, y en 2 Reyes 9:35, los hombres de Jehú solo encuentran el cráneo, los pies y las palmas de las manos de Jezabel tras ser devorada por los perros. En 1 Crónicas 10:10 se registra cómo el cráneo de Saúl fue fijado en el templo de Dagón. La evidencia multilingüe confirma la lectura anatómica: español ''cráneo'', arameo gulgaltā.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90100, 'spa', 'Piel: descubrir, desnudar', 'Piel factitivo (40x): quitar físicamente una cobertura, exponer la desnudez o dejar al descubierto. Concentrado en Levítico 18 (''No descubrirás la desnudez de...'', 18:6-18) y Ezequiel 16, 23. También metafórico: descubrir el cimiento (Hab 3:13), descubrir el escudo (Is 22:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90101, 'spa', 'Hifil: deportar, desterrar', 'Hifil causativo (38x): enviar forzosamente al cautiverio o desplazar a una población. Dominan las deportaciones asirias y babilónicas: 2 R 15:29; 17:6, 11; 24:14-15; 25:11; Jer 52:15; Am 5:27. El vínculo semántico con ''descubrir'' podría ser ''arrancar de la patria''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90107, 'spa', 'Qal: ir al exilio', 'Qal intransitivo (22x): partir al cautiverio. El participio גּוֹלֶה significa ''exiliado, desterrado'' (Is 49:21; 2 R 24:14; Jer 28:6). Jueces 18:30 marca el inicio del exilio de Dan; 2 R 17:23, el de Israel; Isaías 5:13, ''mi pueblo va al cautiverio por falta de conocimiento''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90111, 'spa', 'Hofal: ser deportado', 'Hofal pasivo del Hifil (7x): ser llevado al exilio por un agente externo. Todas las apariciones se vinculan al exilio babilónico: 1 Cr 9:1; Est 2:6 (los antepasados de Mardoqueo); Jer 13:19 (''Judá fue enteramente deportada''). El tronco pasivo lo distingue formalmente del sentido 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90112, 'spa', 'Qal: revelar, descubrir', 'Qal transitivo con objeto abstracto (15x): descubrir información, secretos o la voluntad divina. Casos clásicos: ''Si el Señor no me lo revela'' (1 S 20:12-13), ''el Señor se lo reveló'' (1 S 9:15; 2 S 7:27), Rut 4:4 ''te lo descubriré al oído''. Se solapa parcialmente con el sentido 5 del Piel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90113, 'spa', 'participio: abierto, descubierto', 'Participio pasivo Qal (7x) que describe un estado de apertura o exposición, con valor adjetival. El oráculo de Balaam: ''de ojos abiertos'' (Nm 24:4, 16); el edicto de Ester ''dado a conocer públicamente'' (Est 3:14; 8:13); Pr 27:5 ''mejor es la reprensión manifiesta que el amor oculto''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90115, 'spa', 'Piel: revelar, dar a conocer', 'Piel abstracto (16x): extiende la metáfora del descubrimiento a la revelación de secretos y verdades divinas. Job 12:22 ''Él revela las profundidades''; Sal 98:2 ''El Señor ha dado a conocer su salvación''; Pr 11:13 ''el chismoso descubre el secreto''; Dn 2:22, 28, 29, 47 (cognado arameo).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90116, 'spa', 'Nifal: ser revelado', 'Nifal reflexivo-pasivo (33x): ser descubierto, manifestarse o darse a conocer, frecuentemente referido a la autorrevelación divina. Dios ''se reveló'' a Abraham (Gn 35:7), a Samuel (1 S 3:21); ''el brazo del Señor es revelado'' (Is 53:1). También la vergüenza humana ''queda al descubierto'' (Is 47:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90120, 'spa', 'Qal: partir, desvanecerse', 'Qal intransitivo (6x) con sentido de irse, desaparecer o ser removido, sin implicar exilio propiamente dicho. Icabod: ''la gloria se ha ido'' (1 S 4:21-22); Job 20:28 ''las ganancias de su casa se irán''; Pr 27:25 ''el heno se quita''; Is 24:11 ''toda alegría se ha desvanecido''. Claramente distinto del exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90126, 'spa', 'Hitpael: descubrirse', 'Hitpael reflexivo (2x): exponerse o descubrirse a sí mismo, a menudo de forma vergonzosa. Gn 9:21: Noé ''se descubrió dentro de su tienda''; Pr 18:2: el necio ''se deleita en descubrir su propio corazón''. La evidencia multilingüe confirma la semántica reflexiva. Muy infrecuente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90233, 'spa', 'Desterrar, deportar (Hifil)', 'Desterrar o llevar al cautiverio: forma perfecta Hafel (causativo arameo) haglí, atestiguada en Esdras 4:10 y 5:12. Se refiere a la deportación babilónica: Nabucodonosor ''desterró'' al pueblo de Judá a Babilonia. Aunque comparte la raíz גלה (''descubrir'') con el sentido revelatorio, este significado se desarrolla a partir de la idea de ''descubrir'' una tierra, es decir, vaciarla de sus habitantes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90234, 'spa', 'Revelar, descubrir (arameo)', 'La condición de exilio o cautiverio, especialmente la deportación babilónica pero también las dispersiones asiria y posteriores. Los textos proféticos lo emplean para advertir del juicio venidero (Amós 1:5) o lamentar su cumplimiento (Lamentaciones). El significado raíz de ''descubrir'' añade profundidad teológica: el exilio despoja la seguridad del pacto con la tierra, dejando a Israel expuesto entre las naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90239, 'spa', 'Fuente, manantial', 'Una fuente, manantial o nacimiento de agua natural. En Jos 15:19 y el paralelo de Jue 1:15, Acsa pide a su padre Caleb tierra y recibe ''fuentes de arriba y fuentes de abajo'' (גֻּלֹּת עִלִּיּוֹת y גֻּלֹּת תַּחְתִּיּוֹת). Son fuentes naturales en el Néguev, esenciales para la supervivencia en territorio árido. En español, ''fuentes'' y ''manantiales'' confirman un concepto distinto de agua viva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90240, 'spa', 'Tazón, cuenco', 'Un tazón, cuenco o vasija redondeada — un receptáculo artificial usado en la arquitectura del templo, candelabros e imaginería simbólica. En 1 R 7:41-42 (paralelo en 2 Cr 4:12-13), los dos capiteles en forma de cuenco (גֻּלֹּת) coronan los pilares frente al templo, cubiertos con redes de granadas. En Zac 4:2-3, la גֻּלָּה dorada se asienta sobre la menorá como depósito de aceite que alimenta las lámparas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90247, 'spa', 'ídolos (despectivo)', 'ídolos (despectivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90266, 'spa', 'Exilio, cautividad, deportados', 'El estado o condición de exilio y cautividad, y por extensión metonímica el cuerpo colectivo de deportados. Se usa de forma absoluta para la experiencia del destierro (2 R 25:27; Ez 1:2; 33:21), en cadenas constructas para grupos exiliados específicos (''cautivos de Judá'', Jer 24:5; ''cautivos de Cus'', Is 20:4), y con sufijos divinos para el pueblo desplazado de Yahvé (Is 45:13). Los seis idiomas de traducción convergen en el mismo campo semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90275, 'spa', 'Exilio o cautiverio', 'Exilio o cautiverio — la condición de desplazamiento forzoso, o colectivamente la comunidad de deportados. Aparece solo en las secciones arameas de las Escrituras (Esd 6:16; Dn 2:25; 5:13; 6:13). La forma enfática גָּלוּתָא es paralela al hebreo גּוֹלָה, abarcando desde el estado abstracto de destierro hasta la identidad concreta del grupo exiliado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90276, 'spa', 'Afeitado activo en la raíz Piel', 'Afeitado activo en la raíz Piel: rasurar el cabello, la barba o el vello corporal de alguien. Es el sentido principal (18 apariciones), abarcando la purificación ritual (Lv 14:8-9, la purificación del leproso), las regulaciones del nazireato (Nm 6:9, 18) y eventos narrativos como la preparación de José ante Faraón (Gn 41:14) y la humillación de los enviados de David (2 S 10:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90283, 'spa', 'Reflexivo Hitpael', 'Reflexivo Hitpael: rasurarse a sí mismo, sin intervención de otro. Dos apariciones marcan esta voz: la ley de la persona en cuarentena que «se rasurará él mismo» (Lv 13:33 en ciertas construcciones) y el nazareo que se rasura tras la ofrenda de paz (Nm 6:19). Los pronombres reflexivos en español («se afeitará», «rasurarse él») confirman esta dirección autorreferencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90284, 'spa', 'Pasivo Pual', 'Pasivo Pual: ser rasurado, tener el cabello removido por acción ajena. Tres apariciones registran esta voz: Sansón confiesa «si soy rapado, mi fuerza me dejará» (Jue 16:17), la noticia de que su cabeza «había sido rapada» (Jue 16:22) y los dolientes en Mizpa con «barbas rapadas» (Jer 41:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90298, 'spa', 'Galilea (región)', 'Nombre geográfico propio del distrito septentrional de Israel, centrado en el territorio tribal de Naftalí. El hebreo גָּלִיל significa literalmente «circuito» o «anillo», reflejando el terreno delimitado y ondulante de la región. Las seis ocurrencias bíblicas emplean formas preposicionales («en la Galilea»). Pasajes clave incluyen Jos 20:7, 1 R 9:11 e Is 9:1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90303, 'spa', 'Región o distrito', 'Distrito, región o territorio delimitado, frecuentemente en plural constructo para designar territorios de un pueblo o que bordean un accidente geográfico. Jos 13:2 y Jl 3:4 hablan de ''todas las regiones de los filisteos'' como territorio sin conquistar. Jos 22:10-11 identifica las ''regiones del Jordán'' y Ez 47:8 emplea el singular para ''la región oriental''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90306, 'spa', 'Goliat', 'Nombre propio del gigante filisteo de Gat, principal campeón del ejército filisteo. El nombre podría derivar de una raíz que significa «conspicuo» o «exiliado». Las traducciones multilingües son notablemente uniformes (español «Goliat», francés y alemán «Goliath»). Las seis ocurrencias se agrupan en los relatos de David (1 S 17:4, 23; 21:10; 22:10) y el pasaje paralelo de 2 S 21:19.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90309, 'spa', 'Encomendar, confiar', 'Encomendar, confiar: imperativo Qal en metáfora idiomática, encomendar o confiar el camino, las obras o la carga a Dios, rodando el peso de las preocupaciones sobre el SEÑOR. ''Encomienda al SEÑOR tu camino'' (Sal 37:5); ''encomienda al SEÑOR tus obras'' (Prov 16:3); la burla en la cruz ''se encomendó al SEÑOR'' (Sal 22:8). El salto metafórico es enorme pero arraigado en lo físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90310, 'spa', 'Revolcarse', 'Revolcarse: sentido reflexivo del Hitpael y Pual, revolcarse o rodar sobre sí mismo, típicamente en polvo, cenizas o sangre. Amasa ''se revolcaba en sangre'' en el camino (2 Sam 20:12); las vestiduras de guerra están ''revolcadas en sangre'' (Isa 9:5); los compañeros de Job se ''lanzan'' sobre él en oleadas sucesivas de acusación (Job 30:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90311, 'spa', 'Rodar físicamente', 'Rodar físicamente: el acto básico de rodar un objeto, especialmente una piedra, con 8 apariciones. Los pastores de Jacob ruedan la piedra del pozo (Gén 29:3, 8, 10); Josué ordena rodar piedras contra la entrada de la cueva (Jos 10:18); la afrenta de Egipto es ''quitada rodando'' en Gilgal (Jos 5:9, con un juego de palabras sobre el nombre del lugar y el verbo). Qal y Piel de movimiento físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90312, 'spa', 'Enrollar, plegar', 'Enrollar, plegar: Nifal pasivo, ser enrollado o plegado, dicho de los cielos. Una sola aparición en Isa 34:4: ''todo el ejército de los cielos se disolverá, y los cielos se enrollarán como un pergamino.'' La conjugación pasiva del Nifal indica que los cielos reciben esta acción transformadora en lugar de ejecutarla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90316, 'spa', 'Fluir, correr', 'Fluir, correr: Nifal con metáfora líquida, fluir o correr con fuerza, describiendo el movimiento torrencial de la justicia como un torrente. La única aparición en Amós 5:24 — ''que fluya la justicia como las aguas, y la rectitud como arroyo permanente'' — es uno de los versículos más citados de la literatura profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90317, 'spa', 'Quitar, remover', 'Quitar, remover: imperativo Qal como remover o quitar, rodando el oprobio, la vergüenza o la carga en un acto de liberación. Sal 119:22: ''Quita de mí el oprobio y el menosprecio.'' Aunque etimológicamente conectado con ''rodar,'' las traducciones abandonan la imagen del rodamiento en favor de un lenguaje directo de remoción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90327, 'spa', 'Por causa de, a causa de', 'Por causa de, a causa de: preposición causal que significa ''por causa de, a causa de, por motivo de,'' siempre formada como biglal (beth + galal). Introduce la razón o la persona responsable de una situación, ya sea positiva --Labán reconoce la bendición ''por causa de'' Jacob (Gn 30:27)-- o negativa --Israel sufrirá ''a causa de'' los pecados de Manasés (Jer 15:4). Todas las traducciones principales coinciden en glosas causales directas, confirmando un sentido causal único y estable en las diez apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90333, 'spa', 'Nombre propio levítico', 'Nombre personal de levita que aparece en listas genealógicas postexílicas, referido a dos individuos distintos. Uno figura en 1 Crónicas 9:15, otro en 1 Crónicas 9:16 y Nehemías 11:17 (posiblemente la misma persona en listas paralelas). Las traducciones interlingüísticas conservan el nombre sin modificación, lo cual confirma su carácter de nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90335, 'spa', 'Estiércol o excremento', 'Estiércol o excremento — materia de desecho, particularmente estiércol moldeado o seco usado como combustible o como metáfora de insignificancia. El cognado árabe (jilla) apunta a tortas redondeadas de estiércol de ganado. En Ez 4:12, 15 el excremento humano sirve como combustible contaminante para cocer pan; Job 20:7 lo usa figuradamente para el destino de los impíos; Sof 1:17 lo empareja con sangre derramada como imagen de destrucción total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90339, 'spa', 'Estéril, desolado', 'Estéril, desolado, duro: describe lo improductivo o desprovisto de vida, tanto literal como figuradamente. El cognado árabe jalmad (''roca, tierra pedregosa'') subyace a la imagen de dureza implacable. Se aplica a una noche sin gozo (Job 3:7), a la compañía infructuosa de los malvados (Job 15:34), a vagabundos demacrados por el hambre (Job 30:3) y a Sion exiliada como mujer enlutada (Is 49:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90340, 'spa', 'Provocar contienda', 'Estallar en riña, iniciar una contienda o exponerse en conflicto. Las tres apariciones se hallan en la literatura sapiencial de Proverbios: 17:14 advierte contra dejar estallar la disputa, 18:1 describe al necio que arremete contra la sensatez, y 20:3 señala que todo insensato se enreda en pleitos. La raíz sugiere la idea de algo que erupciona o queda al descubierto.');